CREATE TYPE "ReplyIncidentStatus" AS ENUM ('OPEN','CORRECTION_DRAFTED','CORRECTED','ROOT_CAUSE_FIXED','REGRESSION_ADDED','RESOLVED');
CREATE TABLE "ReplyIncident" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"shopId" TEXT NOT NULL,"conversationId" TEXT NOT NULL,"replyMessageId" TEXT NOT NULL,"replyJobId" TEXT,"errorType" TEXT NOT NULL,"severity" TEXT NOT NULL,"originalAnswerSnapshot" TEXT NOT NULL,"correctedAnswer" TEXT,"rootCause" TEXT,"regressionCaseJson" JSONB,"status" "ReplyIncidentStatus" NOT NULL DEFAULT 'OPEN',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,"resolvedAt" TIMESTAMP(3));
CREATE TABLE "TraceEvent" ("id" TEXT PRIMARY KEY,"workspaceId" TEXT NOT NULL,"tenantId" TEXT NOT NULL,"shopId" TEXT,"conversationId" TEXT,"replyJobId" TEXT,"traceId" TEXT NOT NULL,"stage" TEXT NOT NULL,"payloadJson" JSONB NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "ReplyIncident_workspaceId_tenantId_shopId_conversationId_status_idx" ON "ReplyIncident"("workspaceId","tenantId","shopId","conversationId","status");
CREATE INDEX "TraceEvent_workspaceId_tenantId_conversationId_traceId_createdAt_idx" ON "TraceEvent"("workspaceId","tenantId","conversationId","traceId","createdAt");
